byclass=collections.defaultdict(list)
for l in ls: byclass[l['class']].append(l)
for cl in ['T1_translit','T2_script','T12_script_customer']:
    print('#####',cl)
    for l in byclass[cl][:25]:
        c=cs[l['customer_id']]
        e=w.get(l['expected_uid'])
        print(repr(c['full_name']),'|',c['dob'],'||',(e['primary_name'] if e else None),'|',(e['script_name'] if e else None),'|',(e['dob'] if e else None), '|', [a['name']+':'+a['strength'] for a in e['aliases']] if e else '')
"

