python3 -c "
import json,csv,collections
W=json.load(open('watchlist.json'))
w={e['uid']:e for e in W}
cs={c['customer_id']:c for c in csv.DictReader(open('dev/customers_dev.csv'))}
ls=list(csv.DictReader(open('dev/labels_dev.csv')))
byclass=collections.defaultdict(list)
for l in ls: byclass[l['class']].append(l)
for cl in ['D1_name_dob_conflict','D2_near_name','D3_weak_alias_alone','D4_entity_near_name','D5_partial_dob_conflict','D6_same_given','D7_id_unlisted']:
    print('#####',cl)
    for l in byclass[cl][:22]:
        c=cs[l['customer_id']]
        print(repr(c['full_name']),'|',c['dob'],'|',c['id_type'],c['id_number'],'|',c['type'])
"

python3 -c "
import json,csv,collections,re
W=json.load(open('watchlist.json'))
w={e['uid']:e for e in W}
cs={c['customer_id']:c for c in csv.DictReader(open('dev/customers_dev.csv'))}
ls=list(csv.DictReader(open('dev/labels_dev.csv')))
NAS={'bin','ibn','ben','b.','bint','bn'}
def hasnas(n): return any(t.lower().strip(',') in NAS for t in n.split())
n=0
for l in ls:
    if l['expected_decision']!='MATCH': continue
    e=w[l['expected_uid']]; c=cs[l['customer_id']]
    if hasnas(c['full_name']) and hasnas(e['primary_name']):
        print(repr(c['full_name']),'||',e['primary_name'],'||',[a['name'] for a in e['aliases']])
        n+=1
print('both-nasab matches',n)
"

