NICK_GROUPS = defaultdict(set)


def _build_nick_groups():
    """name -> the other spellings it may stand for.

    Nickname links are *not* made transitive (Ted->Edward and Ted->Theodore
    must not make Edward and Theodore equivalent); the explicit equivalence
    groups are closed.
    """
    rel = defaultdict(set)
    for canon, nicks in NICKNAMES.items():
        for nk in nicks:
            rel[canon].add(nk)
            rel[nk].add(canon)
    for grp in EQUIV_GROUPS:
        for g in grp:
            rel[g] |= set(grp) - {g}
    for name, others in rel.items():
        NICK_GROUPS[name] = others | {name}


_build_nick_groups()

