import collections
import screen

random.seed(11)
entries, lex = screen.load_watchlist('watchlist.json')
index = screen.Index(entries)
raw = json.load(open('watchlist.json', encoding='utf-8'))
by_uid = {e['uid']: e for e in raw}

PART = set(['bin', 'ibn', 'ben', 'b', 'al', 'el', 'de', 'la', 'van', 'der',
            'den', 'du', 'mac', 'mc', 'das', 'do'])


def core_tokens(name):
    out = []
    for t in screen.tokenize(name):
        c = screen.basic_clean(t)
        if not c or c in PART or len(c) == 1:
            continue
        if len(c) >= 7 and screen.PATRON_RE.match(c):
            continue
        out.append(c)
    return out


# pools of given / family names taken from latin primary names
givens = collections.Counter()
families = collections.Counter()
for e in raw:
    if e['type'] != 'individual':
        continue
    pn = e['primary_name']
    if screen.script_kind(pn):
        continue
    ct = core_tokens(pn)
    if len(ct) < 2:
        continue
    givens[ct[0]] += 1
    families[ct[-1]] += 1
givens = [g for g, c in givens.items()]
families = [f for f, c in families.items()]

# name -> set of entries with exactly that (given, family) after cleaning
byname = collections.defaultdict(set)
for e in raw:
    if e['type'] != 'individual':
        continue
    for nm in [e['primary_name']] + [a['name'] for a in e['aliases']
                                     if a['strength'] == 'strong']:
        if screen.script_kind(nm):
            nm2 = None
        ct = core_tokens(nm)
        if len(ct) >= 2:
            byname[(ct[0], ct[-1])].add(e['uid'])
    sn = e.get('script_name')
    if sn:
        ct = core_tokens(sn)
        if len(ct) >= 2:
            byname[(ct[0], ct[-1])].add(e['uid'])


def keys_disjoint(a, b):
    return screen.unit_keys([a]).isdisjoint(screen.unit_keys([b]))


def judge(name, dob, allowed):
    row = {'customer_id': 'X', 'full_name': name, 'dob': dob,
           'nationality': '', 'id_type': '', 'id_number': '',
           'type': 'individual'}
    dec, uid = screen.screen_customer(row, index, lex)
    if dec == 'NO_MATCH':
        return None
    if uid in allowed:
        return None
    return uid


# --- decoy 1: same family, different given -------------------------------
bad = tot = 0
samples = []
for e in raw:
    if e['type'] != 'individual':
        continue
    pn = e['primary_name']
    if screen.script_kind(pn):
        continue
    ct = core_tokens(pn)
    if len(ct) < 2:
        continue
    g0, fam = ct[0], ct[-1]
    for _ in range(4):
        g = random.choice(givens)
        if g != g0 and keys_disjoint(g, g0):
            break
    else:
        continue
    allowed = byname.get((g, fam), set())
    tot += 1
    got = judge(g.title() + ' ' + ' '.join(ct[1:]).title(), '', allowed)
    if got:
        bad += 1
        if len(samples) < 12:
            samples.append((g.title() + ' ' + ' '.join(ct[1:]).title(),
                            pn, got, by_uid[got]['primary_name']))
print('same-family different-given   %4d/%4d fp=%.4f' % (tot - bad, tot,
                                                         bad / max(1, tot)))
for s in samples:
    print('      FP %-38r (from %-30r) -> %s %r' % s)

# --- decoy 2: same given, different family -------------------------------
bad = tot = 0
samples = []
for e in raw:
